const fields = $input.item.json.data.fields;
const get = (label) => fields.find(f => f.label === label)?.value ?? '';

return {
  email: get('Email'),
  brandName: get('Brand name'),
  primaryColor: get('Primary color'),
  styleVibe: get('Style vibe'),
  contentTopic: get('Content topic')
};

